<script setup>
import { ref, onMounted } from 'vue'
import { useLearning, difficultyName } from '../store'
import MathText from '../components/MathText.vue'
const store=useLearning(), keyword=ref(''), knowledge=ref(''), difficulty=ref(''), items=ref([]), total=ref(0), busy=ref(false)
async function search() { busy.value=true; await store.run(async () => { const params=new URLSearchParams({keyword:keyword.value}); if(knowledge.value)params.set('knowledge_id',knowledge.value); if(difficulty.value)params.set('difficulty',difficulty.value); const data=await store.api(`/questions?${params}`);items.value=data.items;total.value=data.total });busy.value=false }
onMounted(search)
</script>
<template><div class="page-heading"><div><p class="eyebrow">{{ store.currentCourse?.name }} · 题库</p><h1>找到此刻需要的一道题</h1><p>按题干关键词、主要或辅助知识点、难度检索。</p></div><span class="badge">拍照搜题未开放</span></div><form class="search-form" @submit.prevent="search"><label class="search-keyword">题干关键词<input v-model="keyword" placeholder="例如：切线、最大值、函数" maxlength="200"/></label><label>知识点<select v-model="knowledge" aria-label="知识点"><option value="">全部知识点</option><option v-for="n in store.nodes" :key="n.id" :value="n.id">{{ n.name }}</option></select></label><label>难度<select v-model="difficulty" aria-label="难度"><option value="">全部难度</option><option value="1">基础</option><option value="2">中等</option><option value="3">提升</option></select></label><button class="primary" :disabled="busy">搜索</button></form><p class="result-count">找到 {{ total }} 道题<span v-if="total>200">，展示前 200 道，请缩小筛选范围</span><span v-if="keyword"> · 关键词“{{ keyword }}”</span></p><div class="search-results"><article v-for="q in items" :key="q.id" class="search-result"><div><span class="badge">{{ store.name(q.knowledge_id) }}</span> <span class="muted">{{ difficultyName(q.difficulty) }}</span></div><h3><MathText :text="q.stem"/></h3><p class="source">{{ q.source }}</p><RouterLink :to="`/practice?question=${q.id}`">作答并查看解析 →</RouterLink></article><div v-if="!items.length && !busy" class="empty"><h2>没有找到匹配的题目</h2><p>试试更短的关键词，或放宽知识点与难度限制。</p></div></div></template>
